import { Controller, Get, Put, Req } from '@nestjs/common';
import type { Request } from 'express';
import * as checks from '../common/checks';
import { transaction } from '../common/db';
import { ApiError } from '../common/errors';
import { currentUser } from '../common/user';

// 가정: 채번 자릿수의 상한 (일련번호 자릿수는 INTEGER 범위 안에서 제한)
const MAX_NUMBERING_DIGITS = 9;
const RESET_CYCLES = ['연', '없음'];

function invalidRule(message: string): ApiError {
  return new ApiError(422, 'INVALID_NUMBERING_RULE', message);
}

@Controller('api/v1')
export class FnSfr01602Controller {
  @Get('/certificate-types/numbering')
  async listCertificateNumberings(@Req() req: Request) {
    const user = currentUser(req);
    user.require('인사 담당자');
    const query = checks.queryOf(req.query);
    const rawPage = query['page'];
    const rawSize = query['size'];
    let page = 0;
    let size = 20;
    if (rawPage !== undefined && rawPage !== null && rawPage !== '') {
      if (!/^\d+$/.test(String(rawPage))) {
        throw new ApiError(400, 'VALIDATION_FAILED', 'page는 0 이상의 숫자여야 합니다.');
      }
      page = Number(rawPage);
    }
    if (rawSize !== undefined && rawSize !== null && rawSize !== '') {
      if (!/^\d+$/.test(String(rawSize)) || Number(rawSize) < 1) {
        throw new ApiError(400, 'VALIDATION_FAILED', 'size는 1 이상의 숫자여야 합니다.');
      }
      size = Math.min(Number(rawSize), 200);
    }
    return transaction(async (db) => {
      const totalRows = await db.query(
        'SELECT COUNT(*) AS "total" FROM certificate_type',
        {},
      );
      const items = await db.query(
        'SELECT certificate_type_id AS "certificateTypeId", '
          + 'name AS "name", '
          + 'numbering_prefix AS "numberingPrefix", '
          + 'numbering_digits AS "numberingDigits", '
          + 'numbering_reset_cycle AS "numberingResetCycle", '
          + 'last_sequence AS "lastSequence" '
          + 'FROM certificate_type '
          + 'ORDER BY certificate_type_id '
          + 'LIMIT CAST(:size AS integer) OFFSET CAST(:offset AS integer)',
        { size, offset: page * size },
      );
      return {
        items,
        page,
        size,
        total: Number(totalRows[0]['total']),
      };
    });
  }

  @Put('/certificate-types/:certificateTypeId/numbering')
  async updateCertificateNumbering(@Req() req: Request) {
    const user = currentUser(req);
    user.require('인사 담당자');
    const data = checks.inputOf(req.body);
    const certificateTypeId = req.params['certificateTypeId'];
    if (!/^\d+$/.test(String(certificateTypeId))) {
      throw new ApiError(400, 'VALIDATION_FAILED', '증명서 종류 ID가 올바르지 않습니다.');
    }
    const prefix = data['numberingPrefix'];
    const digits = data['numberingDigits'];
    const resetCycle = data['numberingResetCycle'];
    if (typeof prefix !== 'string' || prefix.trim() === '') {
      throw invalidRule('채번 접두어를 입력해 주세요.');
    }
    if (prefix.length > 20) {
      throw invalidRule('채번 접두어는 20자 이하로 입력해 주세요.');
    }
    if (
      digits === undefined
      || digits === null
      || digits === ''
      || !/^\d+$/.test(String(digits))
    ) {
      throw invalidRule('채번 자릿수는 1 이상의 정수여야 합니다.');
    }
    if (Number(digits) < 1 || Number(digits) > MAX_NUMBERING_DIGITS) {
      throw invalidRule('채번 자릿수는 1 이상 ' + MAX_NUMBERING_DIGITS + ' 이하여야 합니다.');
    }
    if (typeof resetCycle !== 'string' || !RESET_CYCLES.includes(resetCycle)) {
      throw invalidRule('채번 초기화 주기는 연 또는 없음이어야 합니다.');
    }
    return transaction(async (db) => {
      const found = await db.query(
        'SELECT certificate_type_id AS "certificateTypeId" '
          + 'FROM certificate_type '
          + 'WHERE certificate_type_id = CAST(:id AS bigint)',
        { id: certificateTypeId },
      );
      if (found.length === 0) {
        throw new ApiError(404, 'CERTIFICATE_TYPE_NOT_FOUND', '증명서 종류를 찾을 수 없습니다.');
      }
      await db.execute(
        'UPDATE certificate_type SET '
          + 'numbering_prefix = :prefix, '
          + 'numbering_digits = CAST(:digits AS integer), '
          + 'numbering_reset_cycle = :resetCycle, '
          + 'updated_at = now() '
          + 'WHERE certificate_type_id = CAST(:id AS bigint)',
        {
          prefix: prefix.trim(),
          digits: String(digits),
          resetCycle,
          id: certificateTypeId,
        },
      );
      return { certificateTypeId: Number(certificateTypeId) };
    });
  }
}

