import { useState } from 'react';
import {
  call,
  useData,
  Band,
  DataTable,
  Pager,
  Drawer,
  Form,
  Field,
  TextInput,
  NumberInput,
  Select,
  ErrorText,
  Num,
} from '../kit';
import type { PageProps, Row, Page } from '../kit';

const SIZE = 20;

export default function FnSfr01602Page({ role, notify }: PageProps) {
  const [page, setPage] = useState(0);
  const [editing, setEditing] = useState<Row | null>(null);
  const [prefix, setPrefix] = useState('');
  const [digits, setDigits] = useState<number | string>('');
  const [resetCycle, setResetCycle] = useState('');

  const list = useData<Page>(
    () => call<Page>('GET', '/certificate-types/numbering', role, undefined, { page, size: SIZE }),
    [page, role],
  );

  function openEdit(row: Row) {
    setPrefix(String(row['numberingPrefix'] ?? ''));
    setDigits(row['numberingDigits'] === null || row['numberingDigits'] === undefined ? '' : Number(row['numberingDigits']));
    setResetCycle(String(row['numberingResetCycle'] ?? ''));
    setEditing(row);
  }

  async function save() {
    if (!editing) return;
    if (prefix.trim() === '') {
      throw new Error('채번 접두어를 입력해 주세요.');
    }
    if (digits === '' || Number(digits) < 1) {
      throw new Error('채번 자릿수를 1 이상의 숫자로 입력해 주세요.');
    }
    if (resetCycle === '') {
      throw new Error('채번 초기화 주기를 선택해 주세요.');
    }
    await call(
      'PUT',
      '/certificate-types/' + String(editing['certificateTypeId']) + '/numbering',
      role,
      {
        numberingPrefix: prefix.trim(),
        numberingDigits: digits,
        numberingResetCycle: resetCycle,
      },
    );
    notify('채번 규칙을 저장했습니다.');
    setEditing(null);
    list.reload();
  }

  const data = list.data;

  return (
    <div>
      <h1>증명서별 채번 관리</h1>
      {list.error && <ErrorText text={list.error} />}
      <Band total={data?.total} />
      <DataTable
        columns={[
          { key: 'name', label: '증명서 종류명' },
          { key: 'numberingPrefix', label: '채번 접두어' },
          {
            key: 'numberingDigits',
            label: '채번 자릿수',
            render: (row: Row) => <Num value={row['numberingDigits']} />,
          },
          { key: 'numberingResetCycle', label: '채번 초기화 주기' },
          {
            key: 'lastSequence',
            label: '마지막 일련번호',
            render: (row: Row) => <Num value={row['lastSequence']} />,
          },
          {
            key: 'edit',
            label: '규칙',
            render: (row: Row) => (
              <button className="ghost" onClick={() => openEdit(row)}>
                수정
              </button>
            ),
          },
        ]}
        rows={data?.items ?? []}
        empty="아직 등록한 증명서 종류가 없습니다."
      />
      <Pager page={page} size={SIZE} total={data?.total ?? 0} onPage={setPage} />
      {editing && (
        <Drawer title={'채번 규칙 수정 - ' + String(editing['name'])} onClose={() => setEditing(null)}>
          <Form
            submit="저장"
            onSubmit={save}
            note="저장한 규칙은 이후 승인되는 신청 건부터 적용됩니다."
          >
            <Field label="채번 접두어" required>
              <TextInput value={prefix} onChange={setPrefix} />
            </Field>
            <Field label="채번 자릿수" required>
              <NumberInput value={digits} onChange={setDigits} />
            </Field>
            <Field label="채번 초기화 주기" required>
              <Select
                value={resetCycle}
                onChange={setResetCycle}
                options={[['연', '연'], ['없음', '없음']]}
              />
            </Field>
          </Form>
        </Drawer>
      )}
    </div>
  );
}
